    });
}

function ifEscapeWithTest(string) {
    if (!string || !reHasUnescapedHtml.test(string)) return string;

    return string.replace(reUnescapedHtml, (chr) => {
        if (chr === '&') return '&amp';
        if (chr === '<') return '&lt';
        if (chr === '>') return '&gt';
        if (chr === '"') return '&quot';
        if (chr === "'") return '&#39';
        return chr;
    });
}


function manualConcatEscape(string) {
    if (!string) return string;

    let newstring = "";
